scripts.script:
if (!args.isBroken || !args.target) return;
const eyuEffect = thisItem.effects.getName("恶语");
if (eyuEffect) {
    const existing = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");
    const stacks = existing ? (existing.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 2) {
        await game.xjzl.api.effects.removeEffect(args.target, "wuxue_eyu", 3);
        await args.target.applyDamage({ amount: 10, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="padding: 4px 8px; border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.05);"><div style="color:#8e44ad; font-weight:bold;"><i class="fas fa-comment-slash"></i> 恶语反噬！</div><div style="font-size:0.85em;">恶语叠满三层，在对方脑中炸开，受到 10 点精神伤害！</div></div>` });
    } else {
        const effData = eyuEffect.toObject();
        delete effData._id; effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effData);
    }
}
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="padding: 4px 8px; border-left: 3px solid #c0392b; background: rgba(192,57,43,0.05);"><div style="color:#c0392b; font-weight:bold;"><i class="fas fa-bolt"></i> 乘胜追击！</div><div style="font-size:0.85em;">击破架招成功！你可以消耗反应动作，立即释放实招【血口喷人】。</div></div>` });

if (!args.isHit || !args.target) return;
const eyuEffect = thisItem.effects.getName("恶语");
if (eyuEffect) {
    const existing = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");
    const stacks = existing ? (existing.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 2) {
        await game.xjzl.api.effects.removeEffect(args.target, "wuxue_eyu", 3);
        await args.target.applyDamage({ amount: 10, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="padding: 4px 8px; border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.05);"><div style="color:#8e44ad; font-weight:bold;"><i class="fas fa-comment-slash"></i> 恶语反噬！</div><div style="font-size:0.85em;">恶语叠满三层，在对方脑中炸开，受到 10 点精神伤害！</div></div>` });
    } else {
        const effData = eyuEffect.toObject();
        delete effData._id; effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effData);
    }
}

if (!Macros.checkStance(actor, args) || !args.attacker) return;
const eyuEffect = thisItem.effects.getName("恶语");
if (eyuEffect) {
    const existing = args.attacker.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");
    const stacks = existing ? (existing.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 2) {
        await game.xjzl.api.effects.removeEffect(args.attacker, "wuxue_eyu", 3);
        await args.attacker.applyDamage({ amount: 10, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
        actor.showFloatyText("格挡反噬！", { fill: "#8e44ad" });
    } else {
        const effData = eyuEffect.toObject();
        delete effData._id; effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.attacker, effData);
        actor.showFloatyText("格挡: 施加恶语", { fill: "#e67e22" });
    }
}

if (!args.isHit || !args.target) return;
const hasEyu = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");

if (hasEyu) {
    // 【终极防并发】群攻中打中多个带恶语的目标时，防止音波被触发多次
    if (actor.zhongkouProcessed) return;
    actor.zhongkouProcessed = true;
    setTimeout(() => { actor.zhongkouProcessed = false; }, 2000);

    const neixi = actor.system.stats.neixi.total || 0;
    // 保底最少 1 点精神伤害
    const extraDmg = Math.max(1, Math.floor(neixi * 0.02));

    // 扫描画板上所有存活且带恶语的 Token
    const targetsToDamage = canvas.tokens.placeables.filter(t => 
        t.actor && t.actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu")
    );

    // 自动扣血
    for (const t of targetsToDamage) {
        await t.actor.applyDamage({ amount: extraDmg, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
    }

    // 发送卡片
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #d35400; background:rgba(211,84,0,0.05); margin-left:2px;">
            <div style="color:#d35400; font-weight:bold;"><i class="fas fa-bullhorn"></i> 众口铄金 触发音波共振！</div>
            <div style="font-size:0.85em; margin-top:4px; color:#555;">
                全场共有 <b>${targetsToDamage.length}</b> 名带有[恶语]的敌人受到音波牵连，分别承受了 <b style="color:red;">${extraDmg}</b> 点精神伤害！
            </div>
        </div>`
    });
}

if (!Macros.checkStance(actor, args)) return;
const effData = thisItem.effects.getName("蛛心").toObject();
delete effData._id; effData.origin = thisItem.uuid;
// API 内置最大叠加层数保护（前提是我们在 JSON 中配置了 maxStacks）
await game.xjzl.api.effects.addEffect(actor, effData);
actor.showFloatyText("格挡: 隐秘结网", { fill: "#9b59b6" });

if (!args.isHit || !args.target) return;

// 1. 无架额外毒伤
if (!args.target.system.martial.stanceActive) {
    const qigan = actor.system.stats.qigan.total || 0;
    // 保底最少 1 点毒素伤害
    const poisonDmg = Math.max(1, Math.floor(qigan * 0.08));

    if (poisonDmg > 0) {
        // 自动造成毒素伤害
        await args.target.applyDamage({ amount: poisonDmg, type: "poison", attacker: actor, isHit: true });
        actor.showFloatyText(`无架追击: ${poisonDmg}毒伤`, {fill: "#2ecc71"});

        // 发送卡片
        ChatMessage.create({
            speaker: ChatMessage.getSpeaker({actor: actor}),
            content: `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #2ecc71; background:rgba(46,204,113,0.05); margin-left:2px;">
                <div style="color:#27ae60; font-weight:bold;"><i class="fas fa-spider"></i> 乘隙而入！</div>
                <div style="font-size:0.85em; margin-top:4px; color:#555;">
                    命中无架势目标，注入毒液造成 <b style="color:red;">${poisonDmg}</b> 点毒素伤害！
                </div>
            </div>`
        });
    }
}

// 2. 消耗蛛心施加迟滞
const zhuxin = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_zhuxin");
const stacks = zhuxin ? (zhuxin.getFlag("xjzl-system", "stacks") || 1) : 0;

if (stacks >= 3) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "作丝绊足 - 蛛网收束" },
        content: `<p>你拥有 ${stacks} 层 [蛛心]。</p><p>是否全部消耗，使目标陷入 <b>[迟滞]</b> 一回合？</p>`
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "wuxue_zhuxin", 99);
        await game.xjzl.api.effects.addEffect(args.target, { id: "chizhi", duration: {rounds: 1} });
        ChatMessage.create({ 
            speaker: ChatMessage.getSpeaker({actor: actor}), 
            content: `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #2980b9; background:rgba(41,128,185,0.05); margin-left:2px;"><div style="color:#2980b9; font-weight:bold;"><i class="fas fa-network-wired"></i> 蛛网收束！</div><div style="font-size:0.85em; margin-top:4px; color:#555;">收割所有蛛心，目标陷入迟滞。</div></div>` 
        });
    }
}

if (!args.isBroken || !args.target) return;
const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 1 + (lvl - 1);
await game.xjzl.api.effects.addEffect(args.target, { id: "blind", duration: { rounds: rounds } });
actor.showFloatyText("击破防线: 致盲", { fill: "#e74c3c" });

if (!args.isHit || !args.target) return;
const lvl = Math.max(1, move.computedLevel || 1);
const effData = thisItem.effects.getName("幻毒").toObject();
delete effData._id; effData.origin = thisItem.uuid;
// 记录来源招式的等级，方便幻毒AE内部读取
foundry.utils.setProperty(effData, "flags.xjzl-system.sourceLevel", lvl);
effData.duration = { rounds: 1 };
await game.xjzl.api.effects.addEffect(args.target, effData);

if (!args.isHit || !args.target) return;
await game.xjzl.api.effects.addEffect(args.target, { id: "prone" });

const shencaiMod = Math.floor((actor.system.stats.shencai.total || 0) / 10);
const roll = await new Roll("1d20 + @mod", {mod: shencaiMod}).evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);
await roll.toMessage({ speaker: ChatMessage.getSpeaker({actor: actor}), flavor: `天罗地网 - 神采牵丝 (DC 15)` });

if (roll.total >= 15) {
    const effData = thisItem.effects.getName("蛛心").toObject();
    delete effData._id; effData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effData);
    actor.showFloatyText("成功牵网: +1 蛛心", { fill: "#9b59b6" });
}

const sourceLvl = thisEffect.getFlag("xjzl-system", "sourceLevel") || 1;
const rounds = 1 + (sourceLvl - 1);
await Macros.requestSave({
    target: actor,
    type: "renxing",
    dc: 12,
    label: "幻毒发作",
    damageOnFail: { value: 5, type: "poison" },
    onFail: { id: "unstable", duration: { rounds: rounds } },
    failureText: "幻毒发作，脚步虚浮！",
    successText: "凭惊人韧性压制了幻毒的爆发。"
});

if (args.isHit && args.target) {
    if (!args.target.system.martial?.stanceActive) {
        const sourceEffect = thisItem.effects.getName("幻惑");
        if (sourceEffect) {
            const effectData = sourceEffect.toObject();
            delete effectData._id;
            effectData.origin = thisItem.uuid;
            await game.xjzl.api.effects.addEffect(args.target, effectData);
            actor.showFloatyText("幻惑 +1", { fill: "#8e44ad" });
        }
    }
}

if (Macros.checkStance(actor, args) && args.attacker) {
    const sourceEffect = thisItem.effects.getName("幻惑");
    if (sourceEffect) {
        const effectData = sourceEffect.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.attacker, effectData);
        actor.showFloatyText("幻音反震", { fill: "#8e44ad" });
    }
}

if (args.isBroken && args.target) {
    const sourceEffect = thisItem.effects.getName("幻惑");
    if (sourceEffect) {
        const effectData = sourceEffect.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effectData);
        actor.showFloatyText("幻惑 +1", { fill: "#8e44ad" });
    }
}

if (args.isHit && args.target) {
    const sourceEffect = thisItem.effects.getName("幻惑");
    if (sourceEffect) {
        const effectData = sourceEffect.toObject();
        delete effectData._id;
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effectData);
        actor.showFloatyText("幻惑 +1", { fill: "#8e44ad" });
    }
}

const targets = Array.from(game.user.targets);
if (targets.length === 0) return;
const target = targets[0].actor;
if (!target) return;

// 提取层数与段数
const huanhuo = target.effects.find(e => e.name === "幻惑");
const stacks = huanhuo ? (huanhuo.getFlag("xjzl-system", "stacks") || 1) : 0;
const lvl = Math.max(1, move.computedLevel || 1);

// 基础1段 + 升级额外1段 + 幻惑层数段
const extraHit = lvl > 1 ? 1 : 0;
const totalHits = 1 + extraHit + stacks;

if (totalHits > 1) {
    // 这里的 damage 是已经吃全了所有面板、内功加成后的单段伤害总和
    const baseDamage = args.flags.damageResult.damage;
    const totalDamage = baseDamage * totalHits;
    const bonus = totalDamage - baseDamage;

    args.flags.damageResult.damage = totalDamage;
    args.flags.damageResult.breakdown += `\n+ 多段幻影结算 (${totalHits}段): +${bonus}`;

    actor.showFloatyText(`幻影连击 ${totalHits}段!`, { fill: "#8e44ad", fontSize: 36 });
}

// actor是带有幻惑的人 (攻击者)
if (args.move.type === "feint" && args.target) {
    const martial = args.target.system.martial;
    // 检查目标是否开启了架招
    if (martial && martial.stanceActive && martial.stanceItemId) {
        const stanceItem = args.target.items.get(martial.stanceItemId);
        if (stanceItem) {
            const stanceMove = stanceItem.system.moves.find(m => m.id === martial.stance);
            // 验证对方开的架招是不是千相叠嶂
            if (stanceMove && stanceMove.name.includes("千相叠嶂")) {
                ChatMessage.create({
                    content: `<div class="xjzl-chat-card" style="margin-left: 5px; padding: 5px; border-left: 3px solid #e74c3c; background: rgba(231,76,60,0.05);">
                        <div style="font-weight: bold; color: #e74c3c; margin-bottom: 2px;">
                            <i class="fas fa-exclamation-triangle"></i> 幻音反制触发
                        </div>
                        <div style="font-size:0.9em; color:#555;">
                            <p>你正受到【幻惑】影响，且对方开启了【千相叠嶂】！</p>
                            <hr style="margin:4px 0; border-color:#ccc;">
                            <p style="margin-bottom:0;"><b>注意：</b> 即使你本次虚招对抗成功，对方也可选择消耗你身上 1 层【幻惑】，令本次虚招判定无效，并要求你重新进行虚招对抗！<br><span style="color:#888; font-size:0.8em;">(若对方要求重投，请手动再次执行虚招对抗)</span></p>
                        </div>
                    </div>`,
                    speaker: ChatMessage.getSpeaker({actor: actor})
                });
            }
        }
    }
}

if (!args.target) return ui.notifications.warn("请选择要赋予阵法效果的阵眼目标。");
const eff = thisItem.effects.getName("四藤绞虎阵·效果");
if (eff) {
    const effectData = eff.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="padding: 6px 10px; border-left: 4px solid #27ae60; background: rgba(39,174,96,0.05); border-radius: 4px;">
            <div style="font-weight:bold; color:#27ae60; margin-bottom:4px;"><i class="fas fa-link"></i> 阵眼连结</div>
            <p style="font-size:0.9em; color:#555;">成功为 <b>${args.target.name}</b> 赋予了【四藤绞虎阵·效果】！</p>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

ChatMessage.create({
    content: `<div class="xjzl-chat-card" style="padding: 6px 10px; border-left: 4px solid #27ae60; background: rgba(39,174,96,0.05); border-radius: 4px;">
        <div style="font-weight:bold; color:#27ae60; margin-bottom:4px;"><i class="fas fa-people-arrows"></i> 移花接木触发！</div>
        <p style="font-size:0.9em; color:#555;">当你相邻的阵眼被招式命中时，可将其推离一格并移动到其原位置，由你承受本次攻击。</p>
        <p style="font-size:0.9em; color:#8b0000; font-weight:bold;">⚠️ 纯手动操作：请手动移动 Token，并在受到伤害时加上 5 点格挡值。</p>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

ChatMessage.create({
    content: `<div class="xjzl-chat-card" style="padding: 6px 10px; border-left: 4px solid #2980b9; background: rgba(41,128,185,0.05); border-radius: 4px;">
        <div style="font-weight:bold; color:#2980b9; margin-bottom:4px;"><i class="fas fa-eye-slash"></i> 声东击西触发！</div>
        <p style="font-size:0.9em; color:#555;">你对目标发起了一次佯攻，成功分散了其注意力。</p>
        <p style="font-size:0.9em; color:#8b0000; font-weight:bold;">⚠️ 纯手动操作：请提醒正在攻击的阵眼队友，其本次攻击在弹窗中手动 <b>命中值+5</b>，若命中，手动为目标添加 <b>1层撕裂</b>。</p>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

ChatMessage.create({
    content: `<div class="xjzl-chat-card" style="padding: 6px 10px; border-left: 4px solid #27ae60; background: rgba(39,174,96,0.05); border-radius: 4px;">
        <div style="font-weight:bold; color:#27ae60; margin-bottom:4px;"><i class="fas fa-leaf"></i> 万藤穿心 - 阵眼联动！</div>
        <p style="font-size:0.9em; color:#555;">若直线路径上有另一名阵眼，该阵眼可消耗 <b>[反应动作]</b> 使藤蔓原路返回，对路径上的敌人再次造成 <b>40</b> 点气血流失。</p>
        <p style="font-size:0.9em; color:#8b0000; font-weight:bold;">⚠️ 手动操作：若满足条件且队友发动了反应，请让受波及的敌人手动通过宏再承受 40 伤害，并为其添加“倒地”状态（持续1回合）。</p>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (!args.target) return ui.notifications.warn("请选择要赋予阵法效果的目标（副阵眼或自己）。");
const eff = thisItem.effects.getName("乾坤守御阵·效果");
if (eff) {
    const effectData = eff.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="padding: 6px 10px; border-left: 4px solid #8e44ad; background: rgba(142,68,173,0.05); border-radius: 4px;">
            <div style="font-weight:bold; color:#8e44ad; margin-bottom:4px;"><i class="fas fa-yin-yang"></i> 乾坤结阵</div>
            <p style="font-size:0.9em; color:#555;">成功为 <b>${args.target.name}</b> 赋予了【乾坤守御阵·效果】！</p>
            <p style="font-size:0.8em; color:#8b0000; margin-top:4px;"><b>⚠️ 提示：</b>请手动调整该效果的层数以匹配结阵总人数。其余状态请手动赋予对应角色。</p>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const eff = thisItem.effects.getName("阴阳流转(双倍)");
if (eff) {
    const effectData = eff.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effectData);
}

ChatMessage.create({
    content: `<div class="xjzl-chat-card" style="padding: 6px 10px; border-left: 4px solid #d35400; background: rgba(211,84,0,0.05); border-radius: 4px;">
        <div style="font-weight:bold; color:#d35400; margin-bottom:4px;"><i class="fas fa-exchange-alt"></i> 流阴济阳触发！</div>
        <p style="font-size:0.9em; color:#555;"><b>${actor.name}</b> 获得了 2 回合的【阴阳流转(双倍)】效果，自身的极阴极阳加值已翻倍。</p>
        <p style="font-size:0.9em; color:#8b0000; font-weight:bold;">⚠️ 手动操作：请手动处理 <b>${args.target ? args.target.name : '另一名副阵眼'}</b> 的“极阳”或“极阴”带来的属性加成，并在 2 回合后恢复。</p>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (!args.target || args.target.uuid === actor.uuid) {
    ui.notifications.warn("请选择另一名副阵眼作为目标！");
    return;
}
const s = actor;
const t = args.target;

const sHp = s.system.resources.hp.value;
const sMax = s.system.resources.hp.max;
const tHp = t.system.resources.hp.value;
const tMax = t.system.resources.hp.max;

const sPct = sHp / sMax;
const tPct = tHp / tMax;

const avgPct = (sPct + tPct) / 2;

const newSHp = Math.floor(avgPct * sMax);
const newTHp = Math.floor(avgPct * tMax);

const sDiff = newSHp - sHp;
const tDiff = newTHp - tHp;

await s.update({"system.resources.hp.value": newSHp});
if (t.isOwner) {
    await t.update({"system.resources.hp.value": newTHp});
} else {
    await game.xjzl.api.socket.executeAsGM("updateDocument", t.uuid, {"system.resources.hp.value": newTHp});
}

